def transform(grid):
    if not grid or not grid[0]:
        return grid
    rows, cols = len(grid), len(grid[0])
    output = [row[:] for row in grid]
    # For each row in the rightmost column:
    # If cell is background (3) and left neighbor is pattern (5 or 7), change to 1
    for ri in range(rows):
        ci = cols - 1
        if 0 <= ci < cols:
            if output[ri][ci] == 3:
                if ci > 0 and output[ri][ci-1] in [5, 7]:
                    output[ri][ci] = 1
    return output

